function task = f90_xmed03_definition()
%F90_XMED03_DEFINITION Public ranges, official cases, and task-owned policy.

task = struct();
task.schema = "simuverity.formal90-xmed03-definition.v1";
task.task_id = "F90-XMED-03";
task.model_name = "F90_XMED_03";
task.target_model_file = "F90_XMED_03.slx";
task.stop_time_s = 24.0;
root = localProjectRoot();
packageRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
task.runner = struct( ...
    "reference_model", string(getenv("SIMUVERITY_SEALED_CANDIDATE_PATH")), ...
    "public_spec", fullfile(packageRoot, "public_spec.json"), ...
    "official_scenarios", simuverity_official_scenarios_path());

task.public_inputs = struct( ...
    "target_tv1_initial_mL", localRange(450, 300, 550), ...
    "target_tv1_final_mL", localRange(450, 300, 550), ...
    "target_tv2_initial_mL", localRange(400, 300, 550), ...
    "target_tv2_final_mL", localRange(400, 300, 550), ...
    "target_step_time_s", localRange(10, 8, 12), ...
    "patient1_resistance_cmH2O_per_Lps", localRange(10, 5, 25), ...
    "patient2_resistance_cmH2O_per_Lps", localRange(12, 5, 25), ...
    "patient1_compliance_L_per_cmH2O", localRange(0.045, 0.025, 0.070), ...
    "patient2_compliance_L_per_cmH2O", localRange(0.040, 0.025, 0.070), ...
    "respiratory_rate_bpm", localRange(15, 12, 24), ...
    "peep_cmH2O", localRange(5, 5, 10), ...
    "max_inspiratory_pressure_cmH2O", localRange(30, 22, 35));

task.outputs = struct( ...
    "patient_pressure", struct("channels", 2, ...
        "order", ["patient1_airway_pressure", "patient2_airway_pressure"], ...
        "unit", "cmH2O"), ...
    "patient_flow", struct("channels", 2, ...
        "order", ["patient1_airway_flow", "patient2_airway_flow"], ...
        "unit", "L/s"), ...
    "patient_volume", struct("channels", 2, ...
        "order", ["patient1_lung_volume", "patient2_lung_volume"], ...
        "unit", "mL"), ...
    "branch_command", struct("channels", 2, ...
        "order", ["patient1_branch_opening", "patient2_branch_opening"], ...
        "unit", "normalized_0_to_1"));

task.scenarios = [ ...
    localScenario("nominal_targets", 450, 450, 400, 400, 10, 10, 12, 0.045, 0.040, 15, 5, 30); ...
    localScenario("compliance_mismatch", 420, 420, 420, 420, 9, 10, 10, 0.027, 0.068, 15, 5, 30); ...
    localScenario("resistance_mismatch", 430, 430, 430, 430, 11, 24, 6, 0.045, 0.045, 15, 5, 32); ...
    localScenario("divergent_target_step", 450, 340, 350, 520, 10, 12, 12, 0.045, 0.045, 15, 5, 32); ...
    localScenario("rapid_low_compliance", 360, 410, 360, 390, 8, 18, 20, 0.027, 0.030, 24, 6, 35); ...
    localScenario("slow_high_peep", 500, 430, 420, 480, 12, 8, 16, 0.060, 0.035, 12, 10, 30); ...
    localScenario("crossed_mechanics", 380, 500, 500, 330, 9, 22, 7, 0.030, 0.065, 18, 7, 34); ...
    localScenario("joint_boundary", 320, 520, 520, 320, 11, 25, 23, 0.026, 0.069, 21, 8, 35) ...
    ];

task.weights = struct("A", 0.15, "Q", 0.15, "M", 0.30, ...
    "R", 0.20, "D", 0.20);
task.policy_id = "simuverity-101-v1:f90-xmed-03:scoring";
task.aggregation = "Every score-bearing multi-scenario group uses its worst official scenario.";
end

function root = localProjectRoot()
root = fileparts(mfilename("fullpath"));
for level = 1:4
    root = fileparts(root);
end
end

function value = localRange(nominal, minimum, maximum)
value = struct("nominal", nominal, "minimum", minimum, "maximum", maximum);
end

function s = localScenario(id, tv1a, tv1b, tv2a, tv2b, stepTime, ...
    r1, r2, c1, c2, rate, peep, pressureLimit)
s = struct( ...
    "id", id, ...
    "target_tv1_initial_mL", tv1a, ...
    "target_tv1_final_mL", tv1b, ...
    "target_tv2_initial_mL", tv2a, ...
    "target_tv2_final_mL", tv2b, ...
    "target_step_time_s", stepTime, ...
    "patient1_resistance_cmH2O_per_Lps", r1, ...
    "patient2_resistance_cmH2O_per_Lps", r2, ...
    "patient1_compliance_L_per_cmH2O", c1, ...
    "patient2_compliance_L_per_cmH2O", c2, ...
    "respiratory_rate_bpm", rate, ...
    "peep_cmH2O", peep, ...
    "max_inspiratory_pressure_cmH2O", pressureLimit);
end
